import { Isorun } from 'isorun'
import { readFileSync, writeFileSync } from 'node:fs'

// usage: node run.mjs <image> <scriptFile> <outFile> [vcpus] [memMiB] [diskMiB] [maxMinutes]
const [image, scriptFile, outFile, vcpus = '2', memMiB = '4096', diskMiB = '20480', maxMinutes = '40'] =
  process.argv.slice(2)

const iso = new Isorun()
const sb = await iso.create({
  image,
  vcpus: Number(vcpus),
  memMiB: Number(memMiB),
  diskMiB: Number(diskMiB),
  timeoutSec: Number(maxMinutes) * 60 + 600,
  networkProfile: 'unrestricted',
})
console.log('SANDBOX_ID=' + sb.id)

const sleep = (ms) => new Promise((r) => setTimeout(r, ms))
const sh = (cmd, t = 90) => sb.exec(`sh -c ${JSON.stringify(cmd)}`, t)

try {
  await sb.writeFile('/root/probe.sh', readFileSync(scriptFile, 'utf8'))

  // Ensure bash exists (alpine images ship busybox only).
  await sh(
    'command -v bash >/dev/null 2>&1 || (command -v apk >/dev/null 2>&1 && apk add --no-cache bash coreutils >/dev/null 2>&1) || (command -v apt-get >/dev/null 2>&1 && apt-get update -qq >/dev/null 2>&1 && apt-get install -y -qq bash >/dev/null 2>&1); command -v bash',
    110,
  )

  // Detach: a single foreground exec would blow the SDK's 120s HTTP/2 stream timeout.
  await sh(
    'cd /root && nohup setsid sh -c "bash /root/probe.sh > /root/probe.log 2>&1; echo \\$? > /root/EXIT" >/dev/null 2>&1 < /dev/null & echo LAUNCHED',
    60,
  )

  const deadline = Date.now() + Number(maxMinutes) * 60_000
  let exit = null
  while (Date.now() < deadline) {
    await sleep(15_000)
    let r
    try {
      r = await sh('cat /root/EXIT 2>/dev/null || true; echo "|"; wc -c < /root/probe.log 2>/dev/null || echo 0', 60)
    } catch (e) {
      console.error('poll error (continuing):', e.message)
      continue
    }
    const [code, bytes] = r.stdout.split('|').map((s) => s.trim())
    process.stderr.write(`  [poll] ${new Date().toISOString().slice(11, 19)} bytes=${bytes} exit=${code || '-'}\n`)
    if (code) {
      exit = code
      break
    }
  }

  console.log('SCRIPT_EXIT=' + (exit ?? 'TIMEOUT'))
  let log = ''
  try {
    log = await sb.readFile('/root/probe.log')
  } catch (e) {
    log = '<<could not read probe.log: ' + e.message + '>>'
  }
  writeFileSync(outFile, log)
  console.log('--- log written to ' + outFile + ' (' + log.length + ' bytes) ---')
} finally {
  if (!process.env.KEEP) {
    await sb.destroy()
    console.log('destroyed ' + sb.id)
  } else console.log('KEPT ' + sb.id)
}

