describe('dry run exercises the real write path', () => {
  it('surfaces a database-level failure instead of reporting success', async () => {
    const { runId } = await seed(true);

    const { ctx, result } = mockWorkerCtx({
      run_id: runId,
      worker_id: WORKER_ID,
      items: [
        {
          id: 'bad-item',
          title: 'Unpersistable',
          payload_text: 'body',
          payload_type: 'text',
          // Not a timestamp. The real path fails on this at INSERT time; a dry
          // run must fail identically rather than cheerfully previewing it.
          occurred_at: 'definitely-not-a-timestamp',
        },
      ],
    });
    await streamContent(ctx);

    expect(result().status).toBe(500);
    expect((result().body as { dry_run?: boolean }).dry_run).toBeUndefined();
  });

  it('rolls back entity rows the attribution step created', async () => {
    // Attribution runs on the dry path (it is what makes the event inserts
    // realistic — events carry the entity ids it resolves), so its auto-created
    // entity rows have to come back out with everything else. Under the old
    // skip-the-write design this was enforced by a hand-placed guard; here it
    // is the transaction, which also covers whatever gets added next.
    const sql = getTestDb();
    const { orgId, runId } = await seed(true);

    const before = (await sql`
      SELECT count(*)::int AS n FROM entities WHERE organization_id = ${orgId}
    `) as Array<{ n: number }>;

    const { ctx, result } = mockWorkerCtx(batchFor(runId));
    await streamContent(ctx);
    expect(result().status).toBe(200);

    const after = (await sql`
      SELECT count(*)::int AS n FROM entities WHERE organization_id = ${orgId}
    `) as Array<{ n: number }>;
    expect(after[0].n).toBe(before[0].n);
  });
});
