      typeof e.stderr === "string" ? e.stderr : (e.stderr?.toString() ?? "");
    const detail = (stderr.trim() || e.message || "unknown error")
      .split("\n")
      .slice(0, 2)
      .join(" ")
      .slice(0, 300);
    return { isolated: false, reason: "unshare_denied", detail };
  }
}

