/**
 * `client.feeds.trigger({ feed_id, dry_run: true })` reaches the dry path.
 *
 * `runs.dry_run` shipped with `manage_feeds` as its only proven caller. The
 * ClientSDK is the surface agents actually write against, and its declared
 * input type for `trigger` was `{ feed_id: number }` — no `dry_run`. The
 * obvious reading of that is "the SDK cannot request a dry run", and acting on
 * it would mean plumbing a flag that is already plumbed.
 *
 * It isn't. `feeds.trigger` does not call `createSyncRun`; it forwards its
 * input verbatim through `createActionCaller` to the `trigger_feed` action,
 * whose TypeBox schema already accepts `dry_run`. Scripts are transpiled by
 * esbuild, which strips types without checking them, so the narrow declared
 * type never blocked anything at runtime either.
 *
 * That makes this test the load-bearing artifact of the change: the type and
 * the discovery metadata are being widened to match a behaviour that already
 * exists, and only an assertion against the real chain can tell those apart
 * from a behaviour being added. It runs the whole path — namespace → action
 * caller → manage_feeds → TriggerFeedAction → createSyncRun — and reads the
 * persisted `runs` row rather than trusting the returned payload.
 *
 * The non-dry control is what gives it meaning: without it, a build that
 * hardcoded `dry_run = true` on every triggered run would pass.
 */

import { beforeEach, describe, expect, it } from 'vitest';
import type { Env } from '../../index';
import { buildFeedsNamespace } from '../../sandbox/namespaces/feeds';
import { cleanupTestDatabase, getTestDb } from '../setup/test-db';
import {
  createTestConnection,
  createTestConnectorDefinition,
  seedOwnerContext,
} from '../setup/test-fixtures';

async function seedFeed(slug: string): Promise<{
  feedId: number;
  ctx: Awaited<ReturnType<typeof seedOwnerContext>>['ctx'];
}> {
  const sql = getTestDb();
  const { org, ctx } = await seedOwnerContext();

  await createTestConnectorDefinition({ key: 'rss', name: 'RSS' });
  const conn = await createTestConnection({
    organization_id: org.id,
    connector_key: 'rss',
    slug,
  });

  const feed = (await sql`
    INSERT INTO feeds
      (organization_id, connection_id, feed_key, status, checkpoint,
       created_at, updated_at)
    VALUES
      (${org.id}, ${conn.id}, 'items', 'active', ${sql.json({ cursor: 'c0' })},
       NOW(), NOW())
    RETURNING id
  `) as Array<{ id: number }>;

  return { feedId: Number(feed[0].id), ctx };
}

describe('client.feeds.trigger dry_run', () => {
  beforeEach(async () => {
    await cleanupTestDatabase();
  });

  it('marks the queued run dry when the SDK caller asks for it', async () => {
    const sql = getTestDb();
    const { feedId, ctx } = await seedFeed('rss-sdk-dry');

    const feeds = buildFeedsNamespace(ctx, {} as Env);
    await feeds.trigger({ feed_id: feedId, dry_run: true });

    const runs = (await sql`
      SELECT dry_run FROM runs WHERE feed_id = ${feedId}
    `) as Array<{ dry_run: boolean }>;

    expect(runs).toHaveLength(1);
    expect(runs[0].dry_run).toBe(true);
  });

  it('leaves the run persistent when dry_run is omitted', async () => {
    const sql = getTestDb();
    const { feedId, ctx } = await seedFeed('rss-sdk-wet');

    const feeds = buildFeedsNamespace(ctx, {} as Env);
    await feeds.trigger({ feed_id: feedId });

    const runs = (await sql`
      SELECT dry_run FROM runs WHERE feed_id = ${feedId}
    `) as Array<{ dry_run: boolean }>;

    expect(runs).toHaveLength(1);
    expect(runs[0].dry_run).toBe(false);
  });

  it('does not let a caller-supplied action key redirect the dry flag', async () => {
    // `createActionCaller` strips a caller `action` before forcing the real
    // one. Asserted here because the dry flag rides the same payload: if that
    // strip regressed, `dry_run` could arrive at a handler that ignores it and
    // the caller would get a persistent run while being told it was dry.
    const sql = getTestDb();
    const { feedId, ctx } = await seedFeed('rss-sdk-spoof');

    const feeds = buildFeedsNamespace(ctx, {} as Env);
    await feeds.trigger({
      feed_id: feedId,
      dry_run: true,
      action: 'delete_feed',
    } as { feed_id: number; dry_run?: boolean });

    const runs = (await sql`
      SELECT dry_run FROM runs WHERE feed_id = ${feedId}
    `) as Array<{ dry_run: boolean }>;

    expect(runs).toHaveLength(1);
    expect(runs[0].dry_run).toBe(true);

    const feed = (await sql`
      SELECT status FROM feeds WHERE id = ${feedId}
    `) as Array<{ status: string }>;
    expect(feed[0].status).toBe('active');
  });
});

