/**
 * A device connector that fails to wire must say so.
 *
 * `reconcileDeviceCapabilities` wires each connector concurrently under
 * `Promise.allSettled`. That is the right shape — one connector failing must
 * not strand the rest — but its rejections went nowhere, so a connector that
 * silently failed to wire looked exactly like one that was never advertised.
 *
 * The failure is not hypothetical. `ensureDeviceConnectorWired` derives a
 * connection slug from the manifest's display NAME, so two manifests sharing a
 * name race `ensureUniqueConnectionSlug`: both compute the same free slug, the
 * loser's INSERT trips `connections_org_slug_unique`, and `allSettled`
 * discarded the error. The only symptom was a definition that intermittently
 * did not exist — which is how it was found, as an unexplained ~1-in-8 flake in
 * device-connector-manifests.test.ts.
 *
 * This test drives that real collision rather than stubbing a rejection: a
 * stub would pass against any `allSettled` wrapper and prove nothing about the
 * path that actually fails.
 *
 * It asserts the WARNING, not the wiring outcome. Which of the two racers loses
 * is genuinely nondeterministic, and the fix deliberately does not change that
 * — reconcile is best-effort and the next poll heals it via slug suffixing.
 * What the fix changes is that losing is no longer silent.
 */

import { beforeEach, describe, expect, it, vi } from 'vitest';
import { generateSecureToken } from '../../auth/oauth/utils';
import logger from '../../utils/logger';
import { reconcileDeviceCapabilities } from '../../worker-api/device-reconcile';
import { cleanupTestDatabase, getTestDb } from '../setup/test-db';

const SHARED_NAME = 'Colliding Device Connector';

function manifestFor(key: string, capability: string) {
  return {
    key,
    version: '0.1.0',
    // Same display name on both — this is the collision under test.
    name: SHARED_NAME,
    description: 'Device manifest used to force a connection-slug collision.',
    required_capability: capability,
    runtime: { platforms: ['macos'] },
    auth_schema: { methods: [{ type: 'none' }] },
    feeds_schema: {
      snapshots: {
        key: 'snapshots',
        name: 'Snapshots',
        configSchema: { type: 'object', properties: {} },
        eventKinds: {
          snapshot: {
            metadataSchema: {
              type: 'object',
              required: ['source', 'origin_id'],
              properties: {
                source: { type: 'string' },
                origin_id: { type: 'string' },
              },
            },
          },
        },
      },
    },
  };
}

async function seedFleetWithCollidingManifests() {
  const sql = getTestDb();
  const userId = `user_${generateSecureToken(4)}`;
  const orgId = `org-wirefail-${generateSecureToken(4)}`;
  const workerId = `wk-${generateSecureToken(6)}`;

  await sql`
    INSERT INTO "user" (id, name, email, "emailVerified", "createdAt", "updatedAt")
    VALUES (${userId}, 'Wire Failure Owner', ${`${userId}@test.local`}, true, NOW(), NOW())
  `;
  await sql`
    INSERT INTO "organization" (id, name, slug, visibility, metadata, "createdAt")
    VALUES (
      ${orgId}, 'Wire Failure Org', ${orgId}, 'private',
      ${sql.json({ personal_org_for_user_id: userId })}, NOW()
    )
  `;
  await sql`
    INSERT INTO member (id, "organizationId", "userId", role, "createdAt")
    VALUES (${`mem_${generateSecureToken(4)}`}, ${orgId}, ${userId}, 'owner', NOW())
  `;

  const manifests = {
    'apple.collide_one': {
      manifest_hash: `h1_${generateSecureToken(6)}`,
      received_at: new Date().toISOString(),
      manifest: manifestFor('apple.collide_one', 'screentime'),
    },
    'apple.collide_two': {
      manifest_hash: `h2_${generateSecureToken(6)}`,
      received_at: new Date().toISOString(),
      manifest: manifestFor('apple.collide_two', 'photos'),
    },
  };

  await sql`
    INSERT INTO device_workers
      (user_id, worker_id, platform, app_version, capabilities, label,
       organization_id, connector_manifests, last_seen_at)
    VALUES (
      ${userId}, ${workerId}, 'macos', '0.1.0',
      ${sql.json({ screentime: true, photos: true })}, 'Colliding Mac',
      ${orgId}, ${sql.json(manifests)}, NOW()
    )
  `;

  return { userId, orgId };
}

describe('device connector wire failures are visible', () => {
  beforeEach(async () => {
    await cleanupTestDatabase();
  });

  it('logs the connector key when a concurrent wire loses the slug race', async () => {
    const { userId } = await seedFleetWithCollidingManifests();
    const warn = vi.spyOn(logger, 'warn');

    try {
      // Repeated because the race is probabilistic: the two wires must
      // interleave between ensureUniqueConnectionSlug and the INSERT. Each
      // round is a fresh org, so a round that happens not to collide simply
      // contributes nothing rather than poisoning the next.
      let sawWireFailureLog = false;
      for (let round = 0; round < 12 && !sawWireFailureLog; round++) {
        const fleet = round === 0 ? { userId } : await seedFleetWithCollidingManifests();
        await reconcileDeviceCapabilities(fleet.userId);
        sawWireFailureLog = warn.mock.calls.some(([, msg]) =>
          typeof msg === 'string' ? msg.includes('Failed to wire device connector') : false
        );
      }

      // If the race never fired in 12 rounds the environment is not exercising
      // the path, and a silent pass would be a false negative — say so.
      expect(
        sawWireFailureLog,
        'the slug race never occurred in 12 rounds; this test did not exercise the failure path'
      ).toBe(true);

      const failure = warn.mock.calls.find(([, msg]) =>
        typeof msg === 'string' ? msg.includes('Failed to wire device connector') : false
      );
      const payload = failure?.[0] as { connector_key?: string; err?: string } | undefined;
      // The key is the actionable part — without it an operator knows something
      // failed but not which connector to look at.
      expect(payload?.connector_key).toMatch(/^apple\.collide_(one|two)$/);
