export default async (ctx, client) => {
  // Live prod-verify for #2398 (skip reasons) + #2397 (SDK dry_run type).
  // feed 452 is `postgres`, which is in CLOUD_RESTRICTED_CONNECTOR_KEYS — under
  // LOBU_CLOUD_MODE createSyncRun declines with reason 'cloud_restricted'.
  // dry_run: true so that IF it is not cloud-restricted here, the run persists
  // nothing (that is #2390's guarantee) instead of writing events to the workspace.
  const out: Record<string, unknown> = {};
  try {
    out.result = await client.feeds.trigger({ feed_id: 452, dry_run: true });
  } catch (e) {
    // createActionCaller turns a business-failure result into an error whose
    // message carries the tool's message — which is exactly what we're testing.
    out.thrown = String((e as Error)?.message ?? e);
  }
  return out;
};

export default async (ctx, client) => {
  // feed 441 = midas (server-side, API-key). dry_run:true → the connector runs
