  const f: any = await client.feeds.get({ feed_id: 441 });
  const runs = (f?.recent_runs ?? []).slice(0, 4).map((r: any) => ({
    id: r.id, status: r.status, dry_run: r.dry_run,
    preview: r.dry_run_preview ? (Array.isArray(r.dry_run_preview) ? r.dry_run_preview.length : 'set') : null,
  }));
  return { feed_status: f?.feed?.status ?? f?.status, runs };
};
